mapper.select:
SELECT  FROM annotation a WHERE a.project_id=#{projectId} AND a.document_revision=#{documentRevision}
AND a.status=#{status}
ORDER BY a.created_at,a.annotation_id LIMIT #{fetchLimit} FOR UPDATE

SELECT invalidation_id AS invalidationId,review_id AS reviewId,trigger_version AS triggerVersion,reason_code AS reasonCode
FROM review_invalidation i WHERE project_id=#{projectId} AND trigger_version=#{artifactId}
  AND reason_code='ANNOTATION_OPENED' ORDER BY review_id FOR UPDATE

mapper.update:
UPDATE operation_record o SET response_ref=#{commandJson},revision=revision+1,updated_at=#{now}
WHERE subject_id=#{userId} AND operation_name='RV-04-THREAD-1' AND idempotency_key=#{key}
  AND operation_id=#{operationId} AND target_id=#{documentId} AND request_sha256=#{requestHash} AND state='PROCESSING' AND revision=#{operationRevision}

UPDATE operation_record o SET state='COMPLETED',http_status=201,response_ref=#{response},revision=revision+1,updated_at=#{now}
WHERE subject_id=#{userId} AND operation_name='RV-04-THREAD-1' AND idempotency_key=#{key}
  AND operation_id=#{operationId} AND target_id=#{documentId} AND request_sha256=#{requestHash} AND state='PROCESSING' AND revision=#{operationRevision}

UPDATE document_head d SET revision=revision+1,updated_at=#{now}
WHERE project_id=#{projectId} AND document_id=#{documentId} AND current_document_revision=#{documentRevision}
  AND revision=#{expectedRevision} AND status<>'SIGNED'

UPDATE document_revision_state s SET issue_watermark=issue_watermark+1,revision=revision+1,updated_at=#{now}
WHERE project_id=#{projectId} AND document_revision=#{documentRevision}
  AND issue_watermark=#{issueWatermark} AND evidence_watermark=#{evidenceWatermark}

mapper.select:
SELECT resource_ref FROM audit_event a WHERE subject_id=#{userId} AND project_id=#{projectId} AND action='annotation.created'
  AND result='SUCCESS' AND reason_code IS NULL AND request_id=#{requestId} AND trace_id=#{requestId}
  AND schema_version='1.0.0' AND schema_manifest_sha256=#{manifest} AND created_by=#{userId} AND classification=#{classification}
